const APP_VERSION='0.2.0',VERSION='pocketscan-'+APP_VERSION;
const ASSETS=['./','./index.html','./style.css','./app.mjs','./run-state.mjs','./update.html','./update.mjs','./db.mjs','./media.mjs','./policy.mjs','./export.mjs','./viewer.mjs','./worker.js','./engine/math.mjs','./engine/sfm.mjs','./engine/dense.mjs','./vendor/opencv.js','./vendor/three.module.js','./vendor/three.core.js','./vendor/OrbitControls.js','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',e=>e.waitUntil((async()=>{const cache=await caches.open(VERSION);for(const asset of ASSETS){const response=await fetch(new Request(new URL(asset,self.registration.scope),{cache:'reload',credentials:'same-origin'}));if(!response.ok||new URL(response.url).origin!==self.location.origin)throw Error('Offline asset unavailable');await cache.put(new URL(asset,self.registration.scope),response);}})()));
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('pocketscan-')&&key!==VERSION)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(e.request.method!=='GET'||url.origin!==self.location.origin)return;const allowed=ASSETS.some(a=>new URL(a,self.registration.scope).pathname===url.pathname);if(!allowed)return;e.respondWith((async()=>{const cache=await caches.open(VERSION);if(['./update.html','./update.mjs'].some(a=>new URL(a,self.registration.scope).pathname===url.pathname)){try{const response=await fetch(new Request(e.request,{cache:'no-store'}));if(response.ok)return response;}catch{}}return await cache.match(e.request,{ignoreSearch:true})||fetch(e.request);})());});

self.addEventListener('message',e=>{if(e.data?.type==='GET_VERSION')e.ports?.[0]?.postMessage({version:APP_VERSION});if(e.data?.type==='ACTIVATE_UPDATE')e.waitUntil(self.skipWaiting());});
